1	import type http from "node:http";
2	import { handleChatStream } from "@mastra/ai-sdk";
3	import { RequestContext } from "@mastra/core/request-context";
4	import { toAISdkMessages } from "@mastra/ai-sdk/ui";
5	import { createUIMessageStream, createUIMessageStreamResponse, type UIMessage, type UIMessageChunk } from "ai";
6	import { canUseAgent } from "./auth/access";
7	import { approvalResumeMessage, pendingApprovalIds, withoutPendingApprovals } from "./chat-approvals";
8	import type { SessionUser } from "./auth/session";
9	import { mastra } from "./mastra";
10	import { traceRequest } from "./telemetry";
11	import { USER_ROLE_KEY, WORKSPACE_USER_KEY } from "./mastra/workspace";
12	import { getCaps } from "./usage/caps";
13	import { TURN_BUDGET_KEY, TurnBudget, type TurnUsage } from "./usage/turn-budget";
14	import { isTraceOwner } from "./neatlogs/trace-owners";
15	import {
16	  checkNeatlogsUsageOnce,
17	  isNeatlogsUsage,
18	  isTrackingTrace,
19	  type NeatlogsUsage,
20	  pendingNeatlogsUsage,
21	  trackNeatlogsUsage,
22	} from "./usage/neatlogs-usage";
23	
24	const MAX_BODY_BYTES = 1024 * 1024;
25	
26	export type AgentSummary = { key: string; id: string; name: string; description: string };
27	
28	/** Without a user, returns every agent; with one, only the agents that user may use. */
29	export function listAgents(user?: SessionUser): AgentSummary[] {
30	  return Object.entries(mastra.listAgents())
31	    .map(([key, agent]) => ({
32	      key,
33	      id: agent.id,
34	      name: agent.name,
35	      description: agent.getDescription(),
36	    }))
37	    .filter((agent) => !user || canUseAgent(user, agent.id));
38	}
39	
40	/** Accepts either the Mastra registry key ("cfoAgent") or the agent id ("cfo"). */
41	export function resolveAgentId(keyOrId: string): string | undefined {
42	  return listAgents().find((agent) => agent.key === keyOrId || agent.id === keyOrId)?.id;
43	}
44	
45	/** One persisted chat per user per agent. */
46	export function chatThreadId(userId: string, agentId: string): string {
47	  return `${userId}:${agentId}`;
48	}
49	
50	/** POST /api/chat/:agentId — streams an AI SDK v7 UI message stream (SSE). */
51	export async function handleChat(
52	  agentKeyOrId: string,
53	  req: http.IncomingMessage,
54	  res: http.ServerResponse,
55	  user: SessionUser,
56	): Promise<void> {
57	  if (req.method !== "POST") {
58	    res.writeHead(405, { allow: "POST" }).end();
59	    return;
60	  }
61	  const agentId = resolveAgentId(agentKeyOrId);
62	  if (!agentId) {
63	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
64	    return;
65	  }
66	  if (!canUseAgent(user, agentId)) {
67	    sendJson(res, 403, { error: "Forbidden" });
68	    return;
69	  }
70	
71	  // Memory already holds the history, so only the newest message is taken from the body: either a
72	  // new user message, or the assistant message carrying the user's tool-approval decisions.
73	  let last: UIMessage;
74	  try {
75	    const body = JSON.parse(await readBody(req)) as { messages?: unknown; message?: unknown };
76	    const candidate = (Array.isArray(body?.messages) ? body.messages.at(-1) : body?.message) as UIMessage | undefined;
77	    if (!candidate || typeof candidate.id !== "string" || !Array.isArray(candidate.parts)) throw new Error("message required");
78	    if (candidate.role !== "user" && candidate.role !== "assistant") throw new Error("unsupported role");
79	    last = candidate;
80	  } catch (error) {
81	    const tooLarge = error instanceof BodyTooLargeError;
82	    sendJson(res, tooLarge ? 413 : 400, {
83	      error: tooLarge ? "Request body too large" : "Expected JSON body whose last message is a user message or a tool approval",
84	    });
85	    return;
86	  }
87	
88	  let message: UIMessage;
89	  if (last.role === "user") {
90	    // Namespace the id by user: storage upserts by message id, so a client-chosen id must not hit another user's rows.
91	    message = { ...last, id: `${user.id}:${last.id}` };
92	    await dropPendingApprovals(agentId, user);
93	  } else {
94	    // Approval response: only decisions for approvals pending in the caller's own thread are kept.
95	    // It resumes the suspended run; the message itself is not stored.
96	    const thread = await ownThread(agentId, user);
97	    const stored = thread ? (await thread.memory.recall({ ...thread.ids, perPage: false })).messages : [];
98	    const resume = approvalResumeMessage(last, pendingApprovalIds(stored));
99	    if (!resume) {
100	      sendJson(res, 409, { error: "That approval is no longer pending." });
101	      return;
102	    }
103	    message = resume;
104	  }
105	
106	  // Stop generation when the browser disconnects.
107	  const abort = new AbortController();
108	  res.on("close", () => {
109	    if (!res.writableFinished) abort.abort();
110	  });
111	
112	  // Only the message is taken from the client: other AgentExecutionOptions (instructions,
113	  // maxSteps, tools, runId...) must not be client-controlled. Memory thread and resource always
114	  // come from the session, never from the client, and so does the RequestContext that selects the
115	  // user's private file folder, cfo.ai connection and Neatlogs trace scope (also on approval
116	  // resumes, so an approved delete or cfo.ai change runs as this user). With
117	  // an approval message (last role "assistant"), handleChatStream resumes each approved/denied
118	  // tool call by its run id instead.
119	  // The span covers stream creation and the whole response write, so it ends only once the run
120	  // has finished (or the client disconnected). The thread id is the Neatlogs session, so one
121	  // conversation with an agent groups as a single session.
122	  //
123	  // Each turn (this request) gets a TurnBudget holding the user's caps for this agent; the
124	  // turn-budget processor on every agent adds each model step's usage to it (also for delegated
125	  // sub-agents, which share it through the RequestContext) and stops the run once a cap is
126	  // exceeded. The caps are the ones for the agent the user is chatting with, never a sub-agent's.
127	  //
128	  // Once the trace has ended (after the reply is sent), Neatlogs' own cost and tokens for this
129	  // turn's trace are fetched in the background and saved on the reply as metadata.neatlogsUsage.
130	  const threadId = chatThreadId(user.id, agentId);
131	  const budget = new TurnBudget(getCaps(user.id, agentId));
132	  let savedReply: { id: string; traceId: string } | undefined;
133	  await traceRequest("web", threadId, async (trace) => {
134	    const requestContext = new RequestContext<unknown>([
135	      [WORKSPACE_USER_KEY, user.id],
136	      [USER_ROLE_KEY, user.role],
137	      [TURN_BUDGET_KEY, budget],
138	    ]);
139	    const agentStream = await handleChatStream({
140	      mastra,
141	      agentId,
142	      version: "v7",
143	      params: {
144	        messages: [message],
145	        memory: { thread: threadId, resource: user.id },
146	        requestContext,
147	        abortSignal: abort.signal,
148	      },
149	      onError: (error) => {
150	        console.error("Web chat stream failed", { agentId, error });
151	        return "Sorry, something went wrong while generating a reply.";
152	      },
153	    });
154	    let replyId: string | undefined;
155	    const stream = withTurnUsage(agentStream, budget, trace.traceId, (id) => (replyId = id));
156	    const response = createUIMessageStreamResponse({ stream });
157	
158	    res.writeHead(response.status, Object.fromEntries(response.headers));
159	    res.flushHeaders();
160	    try {
161	      if (response.body) {
162	        for await (const chunk of response.body) {
163	          if (abort.signal.aborted) break;
164	          res.write(chunk);
165	        }
166	      }
167	    } finally {
168	      res.end();
169	      const usage = { ...budget.snapshot(true), traceId: trace.traceId };
170	      trace.setAttributes({
171	        "app.turn_cost_usd": usage.costUsd,
172	        "app.turn_tokens": usage.tokens,
173	        "app.turn_steps": usage.steps,
174	        "app.turn_capped": usage.capped,
175	      });
176	      if (usage.reason) trace.addTags(usage.reason === "cost" ? "cost-capped" : "token-capped");
177	      const savedId = await saveTurnUsage(agentId, user, replyId, usage).catch((error: unknown) => {
178	        console.warn("Could not save turn usage", { agentId, error: error instanceof Error ? error.message : error });
179	        return undefined;
180	      });
181	      if (savedId) savedReply = { id: savedId, traceId: trace.traceId };
182	    }
183	  }, { agentId, role: last.role }, { userId: user.id, threadId, agentId, tags: last.role === "assistant" ? ["approval-resume"] : [] });
184	
185	  // The trace's root span has ended now, so the exporter can flush it. Not awaited: the reply is
186	  // already complete; the browser polls GET .../messages/:id/neatlogs-usage for the result.
187	  if (savedReply) {
188	    const reply = savedReply;
189	    void trackNeatlogsUsage(reply.traceId, (neatlogsUsage) => saveNeatlogsUsage(agentId, user, reply.id, neatlogsUsage));
190	  }
191	}
192	
193	const TURN_USAGE_PART_ID = "turn-usage";
194	
195	/**
196	 * Passes the agent's UI stream through, adding a `data-turn-usage` part after every model step
197	 * (same part id, so the client keeps one up-to-date part per reply) and a final one before the
198	 * reply finishes. A capped reply also gets a closing text note saying why it stopped. The final
199	 * usage is attached to the finish part as `messageMetadata.turnUsage`.
200	 */
201	function withTurnUsage(
202	  stream: ReadableStream<UIMessageChunk>,
203	  budget: TurnBudget,
204	  traceId: string,
205	  onReplyId: (id: string) => void,
206	): ReadableStream<UIMessageChunk> {
207	  return createUIMessageStream({
208	    execute: async ({ writer }) => {
209	      let open = false;
210	      let ended = false;
211	      const writeUsage = (usage: TurnUsage) =>
212	        writer.write({ type: "data-turn-usage", id: TURN_USAGE_PART_ID, data: { ...usage, traceId } });
213	      const writeEnd = (): TurnUsage => {
214	        ended = true;
215	        if (budget.capped) {
216	          const id = `turn-cap-note-${crypto.randomUUID()}`;
217	          writer.write({ type: "text-start", id });
218	          writer.write({ type: "text-delta", id, delta: `\n\n${budget.cappedMessage()}` });
219	          writer.write({ type: "text-end", id });
220	        }
221	        const usage = { ...budget.snapshot(true), traceId };
222	        writeUsage(usage);
223	        return usage;
224	      };
225	      budget.onStep = (usage) => {
226	        if (!open || ended) return;
227	        try {
228	          writeUsage(usage);
229	        } catch {
230	          // The response is already closed (client gone); usage is still saved at the end.
231	        }
232	      };
233	      try {
234	        for await (const part of stream) {
235	          if (part.type === "start") {
236	            open = true;
237	            if (part.messageId) onReplyId(part.messageId);
238	          }
239	          if (part.type === "finish" && open && !ended) {
240	            const usage = writeEnd();
241	            const metadata = typeof part.messageMetadata === "object" && part.messageMetadata ? part.messageMetadata : {};
242	            writer.write({ ...part, messageMetadata: { ...metadata, turnUsage: usage } });
243	            continue;
244	          }
245	          writer.write(part);
246	        }
247	        // A stream that ended without a finish part (aborted or failed) still reports its usage.
248	        if (open && !ended) writeEnd();
249	      } finally {
250	        budget.onStep = undefined;
251	      }
252	    },
253	  });
254	}
255	
256	/**
257	 * Saves the turn's final usage on the stored reply as `metadata.turnUsage`, so a reloaded chat can
258	 * show it, with `metadata.neatlogsUsage` marked pending until Neatlogs' own numbers arrive. Falls
259	 * back to the newest assistant message when the stream did not name the reply. Resolves to the
260	 * reply's id, or undefined when nothing was saved.
261	 */
262	async function saveTurnUsage(
263	  agentId: string,
264	  user: SessionUser,
265	  replyId: string | undefined,
266	  usage: TurnUsage & { traceId: string },
267	): Promise<string | undefined> {
268	  if (usage.steps === 0) return undefined;
269	  const thread = await ownThread(agentId, user);
270	  if (!thread) return undefined;
271	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
272	  const reply = (replyId && messages.find((m) => m.id === replyId && m.role === "assistant")) || [...messages].reverse().find((m) => m.role === "assistant");
273	  if (!reply) return undefined;
274	  const neatlogsUsage = process.env.NEATLOGS_API_KEY ? pendingNeatlogsUsage(usage.traceId) : undefined;
275	  const store = await mastra.getStorage()?.getStore("memory");
276	  await store?.updateMessages({
277	    messages: [{ id: reply.id, content: { ...reply.content, metadata: { ...reply.content.metadata, turnUsage: usage, ...(neatlogsUsage ? { neatlogsUsage } : {}) } } }],
278	  });
279	  return neatlogsUsage ? reply.id : undefined;
280	}
281	
282	/** The caller's own stored assistant message with this id, or undefined. */
283	async function ownReply(agentId: string, user: SessionUser, messageId: string) {
284	  const thread = await ownThread(agentId, user);
285	  if (!thread) return undefined;
286	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
287	  return messages.find((m) => m.id === messageId && m.role === "assistant");
288	}
289	
290	/** Saves Neatlogs' numbers on the reply (re-read first, so other metadata is kept). */
291	async function saveNeatlogsUsage(agentId: string, user: SessionUser, messageId: string, neatlogsUsage: NeatlogsUsage): Promise<void> {
292	  const reply = await ownReply(agentId, user, messageId);
293	  if (!reply) return; // the chat was cleared meanwhile
294	  const store = await mastra.getStorage()?.getStore("memory");
295	  await store?.updateMessages({ messages: [{ id: reply.id, content: { ...reply.content, metadata: { ...reply.content.metadata, neatlogsUsage } } }] });
296	}
297	
298	/** A reply with no answer yet is looked up again at most this often (per request). */
299	const RECHECK_AFTER_MS = 10_000;
300	
301	/**
302	 * GET /api/chat/:agentId/messages/:messageId/neatlogs-usage — Neatlogs' own cost and tokens for one
303	 * of the caller's own replies: `{ neatlogsUsage }` (pending, ready or unavailable). Only replies in
304	 * the caller's own thread are found (404 otherwise), and only the trace id the server saved on that
305	 * reply, recorded as the caller's own trace, is looked up. When no background poll is running for
306	 * it (it gave up, or the server restarted) and the last check is old enough, it is checked once more.
307	 */
308	export async function handleNeatlogsUsage(
309	  agentKeyOrId: string,
310	  messageId: string,
311	  req: http.IncomingMessage,
312	  res: http.ServerResponse,
313	  user: SessionUser,
314	): Promise<void> {
315	  if (req.method !== "GET") {
316	    res.writeHead(405, { allow: "GET" }).end();
317	    return;
318	  }
319	  const agentId = resolveAgentId(agentKeyOrId);
320	  if (!agentId) {
321	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
322	    return;
323	  }
324	  if (!canUseAgent(user, agentId)) {
325	    sendJson(res, 403, { error: "Forbidden" });
326	    return;
327	  }
328	  const reply = await ownReply(agentId, user, messageId);
329	  if (!reply) {
330	    sendJson(res, 404, { error: "Message not found" });
331	    return;
332	  }
333	  const metadata = reply.content.metadata as { neatlogsUsage?: unknown } | undefined;
334	  const stored = isNeatlogsUsage(metadata?.neatlogsUsage) ? metadata.neatlogsUsage : null;
335	  if (!stored || stored.status === "ready" || isTrackingTrace(stored.traceId)) {
336	    sendJson(res, 200, { neatlogsUsage: stored });
337	    return;
338	  }
339	  const lastChecked = Date.parse(stored.checkedAt);
340	  if ((Number.isFinite(lastChecked) && Date.now() - lastChecked < RECHECK_AFTER_MS) || !isTraceOwner(stored.traceId, user.id)) {
341	    sendJson(res, 200, { neatlogsUsage: stored });
342	    return;
343	  }
344	  const fresh = await checkNeatlogsUsageOnce(stored.traceId);
345	  await saveNeatlogsUsage(agentId, user, reply.id, fresh).catch((error: unknown) => {
346	    console.warn("Could not save Neatlogs usage", { agentId, error: error instanceof Error ? error.message : error });
347	  });
348	  sendJson(res, 200, { neatlogsUsage: fresh });
349	}
350	
351	/** GET/DELETE /api/chat/:agentId/history — read or clear the caller's own chat with one agent. */
352	export async function handleChatHistory(
353	  agentKeyOrId: string,
354	  req: http.IncomingMessage,
355	  res: http.ServerResponse,
356	  user: SessionUser,
357	): Promise<void> {
358	  if (req.method !== "GET" && req.method !== "DELETE") {
359	    res.writeHead(405, { allow: "GET, DELETE" }).end();
360	    return;
361	  }
362	  const agentId = resolveAgentId(agentKeyOrId);
363	  if (!agentId) {
364	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
365	    return;
366	  }
367	  if (!canUseAgent(user, agentId)) {
368	    sendJson(res, 403, { error: "Forbidden" });
369	    return;
370	  }
371	
372	  const thread = await ownThread(agentId, user);
373	  if (req.method === "DELETE") {
374	    if (thread) await thread.memory.deleteThread(thread.ids.threadId);
375	    res.writeHead(204).end();
376	    return;
377	  }
378	  if (!thread) {
379	    sendJson(res, 200, { messages: [] });
380	    return;
381	  }
382	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
383	  sendJson(res, 200, { messages: toAISdkMessages(messages, { version: "v7" }) });
384	}
385	
386	/**
387	 * The caller's own saved chat with an agent, or undefined when there is none. The thread id embeds
388	 * the user id and the resource id is checked, so only the caller's own chat is reachable.
389	 */
390	async function ownThread(agentId: string, user: SessionUser) {
391	  const agent = Object.values(mastra.listAgents()).find((a) => a.id === agentId);
392	  const memory = await agent?.getMemory();
393	  const threadId = chatThreadId(user.id, agentId);
394	  const thread = memory ? await memory.getThreadById({ threadId }) : null;
395	  if (!memory || thread?.resourceId !== user.id) return undefined;
396	  return { memory, ids: { threadId, resourceId: user.id } };
397	}
398	
399	/**
400	 * A new user message moves past any approval still awaiting a decision: it is cleared from the
401	 * stored history (so it is no longer offered, and a late decision gets 409) and its suspended run
402	 * is discarded, deleting the same snapshot rows Mastra deletes when an agent run finishes. For an
403	 * approval raised by a delegated sub-agent, the sub-agent's own suspended run is discarded too.
404	 */
405	async function dropPendingApprovals(agentId: string, user: SessionUser): Promise<void> {
406	  const thread = await ownThread(agentId, user);
407	  if (!thread) return;
408	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
409	  const dropped = withoutPendingApprovals(messages);
410	  if (dropped.messages.length === 0) return;
411	  const storage = mastra.getStorage();
412	  await (await storage?.getStore("memory"))?.updateMessages({ messages: dropped.messages });
413	  const workflows = await storage?.getStore("workflows");
414	  for (const runId of dropped.runIds) {
415	    await workflows?.deleteWorkflowRunById({ runId, workflowName: "agentic-loop" });
416	    await workflows?.deleteWorkflowRunById({ runId, workflowName: "executionWorkflow" });
417	  }
418	}
419	
420	export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
421	  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
422	  res.end(JSON.stringify(body));
423	}
424	
425	class BodyTooLargeError extends Error {}
426	
427	async function readBody(req: http.IncomingMessage): Promise<string> {
428	  const chunks: Buffer[] = [];
429	  let size = 0;
430	  for await (const chunk of req) {
431	    size += (chunk as Buffer).length;
432	    if (size > MAX_BODY_BYTES) throw new BodyTooLargeError();
433	    chunks.push(chunk as Buffer);
434	  }
435	  return Buffer.concat(chunks).toString("utf8");
436	}
