1	import { isToolUIPart, type UIMessage } from "ai";
2	
3	/** A stored message, as returned by Mastra Memory recall (MastraDBMessage), narrowed to what is read here. */
4	type StoredMessage = { role: string; content: unknown };
5	
6	/**
7	 * Approval ids ("<runId>::<toolCallId>", the id the AI SDK stream carries) still awaiting a
8	 * decision in a stored thread. Mastra records each suspended approval under the assistant
9	 * message's `content.metadata.pendingToolApprovals` and removes it once the call is resumed.
10	 */
11	export function pendingApprovalIds(messages: readonly StoredMessage[]): Set<string> {
12	  const ids = new Set<string>();
13	  for (const message of messages) {
14	    if (message.role !== "assistant") continue;
15	    const metadata = (message.content as { metadata?: { pendingToolApprovals?: unknown } } | null)?.metadata;
16	    const pending = metadata?.pendingToolApprovals;
17	    if (!pending || typeof pending !== "object") continue;
18	    for (const entry of Object.values(pending)) {
19	      const { runId, toolCallId } = (entry ?? {}) as { runId?: unknown; toolCallId?: unknown };
20	      if (typeof runId === "string" && runId && typeof toolCallId === "string" && toolCallId) {
21	        ids.add(`${runId}::${toolCallId}`);
22	      }
23	    }
24	  }
25	  return ids;
26	}
27	
28	/**
29	 * For dropping approvals the user moved on from: the stored assistant messages that still hold
30	 * pending approvals, reduced to { id, content } with those approvals removed, and the suspended
31	 * agent runs they belonged to. When the approval came from a delegated sub-agent, the entry also
32	 * names that sub-agent's own suspended run (`delegatedRunId`), which is included too. Storage
33	 * merges metadata keys on update, so the key is set to undefined (left out when serialized)
34	 * rather than deleted.
35	 */
36	export function withoutPendingApprovals<M extends StoredMessage & { id: string; content: { metadata?: Record<string, unknown> } }>(
37	  messages: readonly M[],
38	): { messages: Pick<M, "id" | "content">[]; runIds: Set<string> } {
39	  const cleared: Pick<M, "id" | "content">[] = [];
40	  const runIds = new Set<string>();
41	  for (const message of messages) {
42	    const metadata = message.content.metadata;
43	    if (message.role !== "assistant" || !metadata?.pendingToolApprovals) continue;
44	    for (const id of pendingApprovalIds([message])) runIds.add(id.slice(0, id.lastIndexOf("::")));
45	    if (typeof metadata.pendingToolApprovals === "object") {
46	      for (const entry of Object.values(metadata.pendingToolApprovals as object)) {
47	        const { delegatedRunId } = (entry ?? {}) as { delegatedRunId?: unknown };
48	        if (typeof delegatedRunId === "string" && delegatedRunId) runIds.add(delegatedRunId);
49	      }
50	    }
51	    cleared.push({ id: message.id, content: { ...message.content, metadata: { ...metadata, pendingToolApprovals: undefined } } });
52	  }
53	  return { messages: cleared, runIds };
54	}
