56	/**
57	 * Rebuilds a client's approval response as the assistant message handleChatStream resumes from
58	 * (it reads only "approval-responded" tool parts). Keeps only decisions for approvals pending in
59	 * the caller's own thread, so a client cannot resume another user's run, and copies only the
60	 * fields Mastra reads (no client reason text). Undefined when nothing valid is left.
61	 */
62	export function approvalResumeMessage(message: UIMessage, pending: ReadonlySet<string>): UIMessage | undefined {
63	  const parts: UIMessage["parts"] = [];
64	  for (const part of message.parts ?? []) {
65	    if (!isToolUIPart(part) || part.state !== "approval-responded") continue;
66	    const { id, approved } = part.approval ?? {};
67	    if (typeof id !== "string" || typeof approved !== "boolean" || !pending.has(id)) continue;
68	    if (!id.endsWith(`::${part.toolCallId}`)) continue;
69	    parts.push({ ...part, approval: { id, approved }, state: "approval-responded" } as UIMessage["parts"][number]);
70	  }
71	  return parts.length > 0 ? { id: message.id, role: "assistant", parts } : undefined;
72	}
