36	/** Usage and caps of one chat turn: every model step of the agent and of any agent it delegates to. */
37	export class TurnBudget {
38	  inputTokens = 0;
39	  outputTokens = 0;
40	  cachedInputTokens = 0;
41	  costUsd = 0;
42	  steps = 0;
43	  reason: CapReason | null = null;
44	  /** Called after every recorded model step (the server streams it as `data-turn-usage`). */
45	  onStep?: (usage: TurnUsage) => void;
46	
47	  constructor(readonly caps: TurnCaps) {}
48	
49	  get tokens(): number {
50	    return this.inputTokens + this.outputTokens;
51	  }
52	
53	  get capped(): boolean {
54	    return this.reason !== null;
55	  }
56	
57	  /** Adds one model step's usage, then marks the turn capped once either cap is exceeded. */
58	  record(modelId: string | undefined, usage: StepUsage | undefined): void {
59	    const input = safeCount(usage?.inputTokens);
60	    // Reasoning tokens are part of the output count; if a provider reports a larger total, the
61	    // difference is counted as output so nothing goes uncounted.
62	    const output = Math.max(safeCount(usage?.outputTokens), safeCount(usage?.totalTokens) - input);
63	    this.inputTokens += input;
64	    const cached = Math.min(safeCount(usage?.cachedInputTokens), input);
65	    this.outputTokens += output;
66	    this.cachedInputTokens += cached;
67	    this.costUsd += estimateCostUsd(modelId, input, output, cached);
68	    this.steps += 1;
