78	      costUsd: round(this.costUsd),
79	      tokens: this.tokens,
80	      inputTokens: this.inputTokens,
81	      outputTokens: this.outputTokens,
82	      cachedInputTokens: this.cachedInputTokens,
83	      steps: this.steps,
84	      capCostUsd: this.caps.costCapUsd,
85	      capTokens: this.caps.tokenCap,
86	      capped: this.capped,
87	      reason: this.reason,
88	      final,
89	    };
90	  }
91	
92	  /** User-facing explanation, used as the note on a capped reply. */
93	  cappedMessage(): string {
