37	/** Lets a request annotate its own trace root span once it knows more (e.g. a capped turn). */
38	export type TraceHandle = {
39	  /** The Neatlogs (OpenTelemetry) trace id of this request. */
40	  traceId: string;
41	  addTags(...tags: string[]): void;
42	  setAttributes(attributes: Record<string, string | number | boolean>): void;
43	};
44	
45	export async function traceRequest<T>(
46	  channel: "cli" | "web",
47	  sessionId: string,
48	  run: (trace: TraceHandle) => Promise<T>,
49	  input?: unknown,
50	  context: TraceContext = {},
51	): Promise<T> {
52	  await telemetryReady;
53	  const { userId, threadId, agentId } = context;
54	  const department = agentId ? DEPARTMENT_TAGS[agentId] : undefined;
55	  const tags = [...(context.tags ?? []), ...(department ? [department] : [])];
56	  return trace({
57	    name: `${channel}.request`,
58	    kind: "WORKFLOW",
59	    sessionId: channel === "web" && threadId ? threadId : sessionId,
60	    sessionEntryPoint: channel,
61	    endUserId: userId,
62	    input,
63	    tags,
64	    // OpenTelemetry attributes must be primitives, so metadata is serialized.
65	    metadata: JSON.stringify({ agentId, threadId, channel }),
66	    attributes: {
67	      "app.channel": channel,
68	      ...(agentId ? { "app.agent_id": agentId } : {}),
69	      ...(threadId ? { "app.thread_id": threadId } : {}),
70	    },
71	  }, async (activeSpan) => {
72	    const traceId = activeSpan.spanContext().traceId;
73	    console.info("Neatlogs trace started", { channel, traceId, sessionId, agentId });
74	    // Web traces belong to the signed-in user; the Neat Bot shows non-admins only their own.
75	    if (channel === "web" && userId) {
76	      try {
77	        recordTraceOwners(userId, [traceId]);
78	      } catch (error) {
79	        console.warn("[neatlogs] could not record trace owner:", error instanceof Error ? error.message : error);
80	      }
81	    }
82	    // trace() records `tags` as the root span's "tags" attribute; re-setting it adds tags later.
83	    const handle: TraceHandle = {
84	      traceId,
85	      addTags: (...extra) => {
86	        for (const tag of extra) if (!tags.includes(tag)) tags.push(tag);
87	        activeSpan.setAttribute("tags", [...tags]);
88	      },
89	      setAttributes: (attributes) => activeSpan.setAttributes(attributes),
90	    };
91	    log("Request started", { channel });
92	    try {
93	      const result = await run(handle);
94	      log("Request completed", { channel });
95	      return result;
96	    } catch (error) {
97	      log("Request failed", { channel, level: "error", error: error instanceof Error ? error.message : String(error) });
98	      throw error;
99	    }
100	  });
101	}
