// Test client for the isolated :3001 instance. Never prints the password.
// usage: node client.mjs <cmd> [args]
//   caps-get | caps-put <usd> <tokens> | caps-delete | clear | history
//   ask "<text>" | decide <escalationId> <approve|deny> | raw-ask "<text>"
import { readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE ?? "http://localhost:3001";
const AGENT = process.env.AGENT ?? "assistant";
const USER = process.env.TEST_USER ?? "adminuser1";
const SCRATCH = new URL(".", import.meta.url).pathname;
const COOKIE_FILE = `${SCRATCH}cookie-${USER}.txt`;

async function cookie() {
  try {
    return readFileSync(COOKIE_FILE, "utf8");
  } catch {}
  const seed = JSON.parse(readFileSync("/Users/apple/Open/nlhack/seed-users.json", "utf8"));
  const users = Array.isArray(seed) ? seed : seed.users;
  const u = users.find((x) => x.username === USER);
  const res = await fetch(`${BASE}/api/auth/sign-in/username`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: BASE },
    body: JSON.stringify({ username: u.username, password: u.password }),
  });
  if (!res.ok) throw new Error(`sign-in ${res.status} ${await res.text()}`);
  const c = res.headers.getSetCookie().map((x) => x.split(";")[0]).join("; ");
  writeFileSync(COOKIE_FILE, c);
  return c;
}

async function api(path, init = {}) {
  const res = await fetch(`${BASE}${path}`, { ...init, headers: { cookie: await cookie(), "content-type": "application/json", origin: BASE, ...(init.headers ?? {}) } });
  return res;
}

async function chat(message) {
  const t0 = Date.now();
  const res = await api(`/api/chat/${AGENT}`, { method: "POST", body: JSON.stringify({ message }) });
  if (!res.ok) {
    console.log("HTTP", res.status, await res.text());
    return;
  }
  const raw = await res.text();
  const parts = raw.split("\n").filter((l) => l.startsWith("data: ") && l !== "data: [DONE]").map((l) => JSON.parse(l.slice(6)));
  let text = "";
  const tools = [];
  let usage;
  for (const p of parts) {
    if (p.type === "text-delta") text += p.delta;
    if (p.type === "tool-input-available") tools.push({ id: p.toolCallId, name: p.toolName, input: p.input });
    if (p.type === "tool-output-available" || p.type === "tool-output-error") {
      const t = tools.find((x) => x.id === p.toolCallId);
      if (t) t.out = p.type === "tool-output-error" ? `ERROR ${p.errorText}` : JSON.stringify(p.output).length + " chars";
    }
    if (p.type === "data-turn-usage") usage = p.data;
    if (p.type === "error") console.log("STREAM ERROR", p.errorText);
  }
  writeFileSync(`${SCRATCH}last-stream.json`, JSON.stringify(parts, null, 1));
  console.log(`--- ${((Date.now() - t0) / 1000).toFixed(1)}s, ${parts.length} parts`);
  console.log("TOOLS", JSON.stringify(tools.map((t) => ({ name: t.name, input: t.input, out: t.out }))));
  console.log("TEXT\n" + text);
  console.log("USAGE", JSON.stringify(usage));
}

const [cmd, ...args] = process.argv.slice(2);
const id = () => `test-${Date.now()}`;
if (cmd === "caps-get") console.log(await (await api(`/api/agents/${AGENT}/caps`)).text());
else if (cmd === "caps-put")
  console.log(await (await api(`/api/agents/${AGENT}/caps`, { method: "PUT", body: JSON.stringify({ costCapUsd: Number(args[0]), tokenCap: Number(args[1]) }) })).text());
else if (cmd === "caps-delete") console.log(await (await api(`/api/agents/${AGENT}/caps`, { method: "DELETE" })).text());
else if (cmd === "clear") console.log((await api(`/api/chat/${AGENT}/history`, { method: "DELETE" })).status);
else if (cmd === "history") {
  const h = await (await api(`/api/chat/${AGENT}/history`)).json();
  writeFileSync(`${SCRATCH}history.json`, JSON.stringify(h, null, 1));
  for (const m of h.messages) {
    console.log(`== ${m.role} ${m.id} meta=${JSON.stringify(m.metadata ?? {}).slice(0, 400)}`);
    for (const p of m.parts) {
      if (p.type === "text") console.log("  text:", p.text.slice(0, 300).replace(/\n/g, " "));
      else if (p.type.startsWith("tool-") || p.type === "dynamic-tool")
        console.log("  ", p.type, p.state, JSON.stringify(p.input).slice(0, 120), "->", p.output !== undefined ? JSON.stringify(p.output).length + " chars" : p.errorText);
      else console.log("  ", p.type);
    }
  }
} else if (cmd === "ask") await chat({ id: id(), role: "user", parts: [{ type: "text", text: args[0] }] });
else if (cmd === "decide")
  await chat({ id: id(), role: "user", parts: [{ type: "text", text: args[1] }], metadata: { capEscalation: { id: args[0], approved: args[1] === "approve" } } });
else console.log("unknown cmd");

