import { neatlogsMcp } from "/Users/apple/Open/nlhack/src/mastra/tools/neatlogs.ts";

const [traceId, toolName = "get_trace_context", extra = "{}"] = process.argv.slice(2);
const tools = await neatlogsMcp.listTools();
if (traceId === "list") {
  console.log(Object.keys(tools).join("\n"));
} else {
  const tool = tools[`neatlogs_${toolName}`];
  const out = await tool.execute!({ trace_id: traceId, ...JSON.parse(extra) } as never, {} as never);
  console.log(typeof out === "string" ? out : JSON.stringify(out, null, 1));
}
await neatlogsMcp.disconnect();
process.exit(0);

